import{_ as t,o as r,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"UC 02 — Agency & Workspace (UC-13 → UC-31)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/02-agency-workspace.md","filePath":"ba/use-cases/02-agency-workspace.md"}'),a={name:"ba/use-cases/02-agency-workspace.md"};function s(n,e,l,c,d,g){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="uc-02-—-agency-workspace-uc-13-→-uc-31" tabindex="-1">UC 02 — Agency &amp; Workspace (UC-13 → UC-31) <a class="header-anchor" href="#uc-02-—-agency-workspace-uc-13-→-uc-31" aria-label="Permalink to &quot;UC 02 — Agency &amp; Workspace (UC-13 → UC-31)&quot;">​</a></h1><p>&gt; <a href="./../00-overview.html">&lt;&lt; Về Overview</a> · Nguồn FR: <a href="./../03-agency-workspace-management.html">03-agency-workspace-management.md</a> &gt; Nguồn UC gốc: <code>Các FR của hệ thống - Use Case.csv</code></p><h2 id="bang-tong-hop" tabindex="-1">Bảng tổng hợp <a class="header-anchor" href="#bang-tong-hop" aria-label="Permalink to &quot;Bảng tổng hợp&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UC ID</th><th>Use Case</th><th>Actor(s)</th><th>Related FR</th></tr></thead><tbody><tr><td>UC-13</td><td>View Agency List &amp; Dashboard</td><td>OWNER</td><td>3.4.1, 3.4.2</td></tr><tr><td>UC-14</td><td>Create Agency</td><td>OWNER</td><td>3.4.3</td></tr><tr><td>UC-15</td><td>View Agency Profile</td><td>OWNER</td><td>3.4.4</td></tr><tr><td>UC-16</td><td>Update Agency Profile</td><td>OWNER</td><td>3.4.5</td></tr><tr><td>UC-17</td><td>Delete Agency</td><td>OWNER</td><td>3.4.6</td></tr><tr><td>UC-18</td><td>Invite Agency Member</td><td>OWNER</td><td>3.4.7</td></tr><tr><td>UC-19</td><td>View Agency Invitation Status</td><td>OWNER</td><td>3.4.8</td></tr><tr><td>UC-20</td><td>Remove Agency Member</td><td>OWNER</td><td>3.4.9</td></tr><tr><td>UC-21</td><td>View Workspace List &amp; Dashboard</td><td>OWNER/MEMBER</td><td>3.4.10, 3.4.11</td></tr><tr><td>UC-22</td><td>Create Workspace</td><td>OWNER/MANAGER</td><td>3.4.12</td></tr><tr><td>UC-23</td><td>View Workspace Profile</td><td>OWNER/MANAGER</td><td>3.4.13</td></tr><tr><td>UC-24</td><td>Update Workspace Profile</td><td>OWNER/MANAGER</td><td>3.4.14</td></tr><tr><td>UC-25</td><td>Delete Workspace</td><td>OWNER</td><td>3.4.15</td></tr><tr><td>UC-26</td><td>Leave Workspace</td><td>MEMBER</td><td>3.4.16</td></tr><tr><td>UC-27</td><td>Save Workspace Template</td><td>OWNER</td><td>3.4.17</td></tr><tr><td>UC-28</td><td>View Workspace Members</td><td>OWNER/MANAGER</td><td>3.4.18</td></tr><tr><td>UC-29</td><td>Add Workspace Member</td><td>OWNER/MANAGER</td><td>3.4.19</td></tr><tr><td>UC-30</td><td>Update Workspace Member Role</td><td>OWNER/MANAGER</td><td>3.4.20</td></tr><tr><td>UC-31</td><td>Remove Workspace Member</td><td>OWNER/MANAGER</td><td>3.4.21</td></tr></tbody></table><hr><h2 id="uc-13-—-view-agency-list-dashboard" tabindex="-1">UC-13 — View Agency List &amp; Dashboard <a class="header-anchor" href="#uc-13-—-view-agency-list-dashboard" aria-label="Permalink to &quot;UC-13 — View Agency List &amp; Dashboard&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> View the list of Agencies owned and the overview dashboard for each Agency.</li><li><strong>Precondition:</strong> User authenticated.</li><li><strong>Main Flow:</strong><ol><li>OWNER opens Agency List screen.</li><li>System lists all Agencies where <code>owner_id</code> = current user.</li><li>OWNER selects an Agency → system shows Agency Dashboard (overview stats).</li></ol></li></ul><h2 id="uc-14-—-create-agency" tabindex="-1">UC-14 — Create Agency <a class="header-anchor" href="#uc-14-—-create-agency" aria-label="Permalink to &quot;UC-14 — Create Agency&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER (any USER becomes OWNER upon creation)</li><li><strong>Description:</strong> Create a new Agency, linked to the owner&#39;s account.</li><li><strong>Precondition:</strong> User authenticated.</li><li><strong>Main Flow:</strong><ol><li>USER opens Create Agency form, enters Agency name/profile info.</li><li>System creates Agency with <code>owner_id</code> = current user (1:1).</li></ol></li><li><strong>Postcondition:</strong> New Agency exists; creator becomes its unique OWNER.</li></ul><h2 id="uc-15-—-view-agency-profile" tabindex="-1">UC-15 — View Agency Profile <a class="header-anchor" href="#uc-15-—-view-agency-profile" aria-label="Permalink to &quot;UC-15 — View Agency Profile&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> View the Agency&#39;s representative profile information.</li><li><strong>Precondition:</strong> OWNER of the Agency.</li><li><strong>Main Flow:</strong><ol><li>OWNER opens Agency Profile screen.</li><li>System displays Agency profile fields (used to represent the Agency to Clients).</li></ol></li></ul><h2 id="uc-16-—-update-agency-profile" tabindex="-1">UC-16 — Update Agency Profile <a class="header-anchor" href="#uc-16-—-update-agency-profile" aria-label="Permalink to &quot;UC-16 — Update Agency Profile&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> Update the Agency&#39;s representative profile information.</li><li><strong>Precondition:</strong> OWNER of the Agency.</li><li><strong>Main Flow:</strong><ol><li>OWNER edits Agency profile fields, submits.</li><li>System validates and persists changes.</li></ol></li></ul><h2 id="uc-17-—-delete-agency" tabindex="-1">UC-17 — Delete Agency <a class="header-anchor" href="#uc-17-—-delete-agency" aria-label="Permalink to &quot;UC-17 — Delete Agency&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> Soft-delete an Agency with confirmation; recoverable within 30 days.</li><li><strong>Precondition:</strong> OWNER of the Agency.</li><li><strong>Main Flow:</strong><ol><li>OWNER requests Agency deletion, confirms via modal.</li><li>System soft-deletes Agency (all Workspaces/members lose access).</li></ol></li><li><strong>Postcondition:</strong> Agency recoverable for 30 days, then permanently purged.</li></ul><h2 id="uc-18-—-invite-agency-member" tabindex="-1">UC-18 — Invite Agency Member <a class="header-anchor" href="#uc-18-—-invite-agency-member" aria-label="Permalink to &quot;UC-18 — Invite Agency Member&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> Invite a new member into the Agency via email/notification.</li><li><strong>Precondition:</strong> OWNER of the Agency.</li><li><strong>Main Flow:</strong><ol><li>OWNER enters invitee email, sends invitation.</li><li>System notifies invitee via email + in-app notification.</li><li>Invitee accepts → becomes Agency Member (no role yet — role only exists at Workspace level).</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Invitation not accepted within 3 days → auto-expires.</li></ul></li></ul><h2 id="uc-19-—-view-agency-invitation-status" tabindex="-1">UC-19 — View Agency Invitation Status <a class="header-anchor" href="#uc-19-—-view-agency-invitation-status" aria-label="Permalink to &quot;UC-19 — View Agency Invitation Status&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER, USER (invited)</li><li><strong>Description:</strong> Track the status of a sent invitation (invitation expires after 3 days).</li><li><strong>Precondition:</strong> An invitation exists.</li><li><strong>Main Flow:</strong><ol><li>Either OWNER or the invited USER opens Invitation Status view.</li><li>System shows status: Pending / Accepted / Rejected / Expired.</li></ol></li></ul><h2 id="uc-20-—-remove-agency-member" tabindex="-1">UC-20 — Remove Agency Member <a class="header-anchor" href="#uc-20-—-remove-agency-member" aria-label="Permalink to &quot;UC-20 — Remove Agency Member&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> Remove an existing member from the Agency.</li><li><strong>Precondition:</strong> OWNER of the Agency; target is an existing Agency Member.</li><li><strong>Main Flow:</strong><ol><li>OWNER selects member, confirms removal.</li><li>System removes Agency membership (member loses access to all Workspaces of this Agency).</li></ol></li><li><strong>Business Rule:</strong> Resources the removed member created remain (shared asset) — re-adding restores continued access.</li></ul><h2 id="uc-21-—-view-workspace-list-dashboard" tabindex="-1">UC-21 — View Workspace List &amp; Dashboard <a class="header-anchor" href="#uc-21-—-view-workspace-list-dashboard" aria-label="Permalink to &quot;UC-21 — View Workspace List &amp; Dashboard&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MEMBER</li><li><strong>Description:</strong> View the list of Workspaces and the overview/statistics for each Workspace.</li><li><strong>Precondition:</strong> User authenticated.</li><li><strong>Main Flow:</strong><ol><li>OWNER: system lists all Workspaces under their Agency.</li><li>MEMBER: system lists only Workspaces the member currently belongs to.</li><li>User selects a Workspace → Workspace Dashboard shown.</li></ol></li></ul><h2 id="uc-22-—-create-workspace" tabindex="-1">UC-22 — Create Workspace <a class="header-anchor" href="#uc-22-—-create-workspace" aria-label="Permalink to &quot;UC-22 — Create Workspace&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER</li><li><strong>Description:</strong> Create a new Workspace and assign a Manager to it.</li><li><strong>Precondition:</strong> OWNER of the parent Agency.</li><li><strong>Main Flow:</strong><ol><li>OWNER opens Create Workspace form.</li><li>OWNER assigns exactly one Manager (may self-assign).</li><li>System creates Workspace, sets <code>created_by</code>, assigns the chosen Manager as the sole <code>MANAGER</code> MemberRole.</li></ol></li><li><strong>Business Rule:</strong> Exactly 1 Manager per Workspace at all times — no co-management; reassigning Manager revokes the previous one&#39;s Manager role.</li></ul><h2 id="uc-23-—-view-workspace-profile" tabindex="-1">UC-23 — View Workspace Profile <a class="header-anchor" href="#uc-23-—-view-workspace-profile" aria-label="Permalink to &quot;UC-23 — View Workspace Profile&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER</li><li><strong>Description:</strong> View the Workspace&#39;s profile information, including Timezone configuration.</li><li><strong>Precondition:</strong> MANAGER of the Workspace, or OWNER of parent Agency.</li><li><strong>Main Flow:</strong><ol><li>User opens Workspace Profile screen.</li><li>System displays Workspace fields including Timezone config (used to optimize post-scheduling by location).</li></ol></li></ul><h2 id="uc-24-—-update-workspace-profile" tabindex="-1">UC-24 — Update Workspace Profile <a class="header-anchor" href="#uc-24-—-update-workspace-profile" aria-label="Permalink to &quot;UC-24 — Update Workspace Profile&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER</li><li><strong>Description:</strong> Update the Workspace&#39;s profile information, including Timezone configuration.</li><li><strong>Precondition:</strong> MANAGER of the Workspace.</li><li><strong>Main Flow:</strong><ol><li>MANAGER edits Workspace fields (name, timezone, etc.), submits.</li><li>System validates and persists changes.</li></ol></li></ul><h2 id="uc-25-—-delete-workspace" tabindex="-1">UC-25 — Delete Workspace <a class="header-anchor" href="#uc-25-—-delete-workspace" aria-label="Permalink to &quot;UC-25 — Delete Workspace&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> Delete a Workspace (recoverable within 30 days), moving related data to an inactive state.</li><li><strong>Precondition:</strong> OWNER of the parent Agency.</li><li><strong>Main Flow:</strong><ol><li>OWNER requests Workspace deletion, confirms via modal.</li><li>System soft-deletes Workspace; all members lose access; related data set inactive.</li></ol></li><li><strong>Postcondition:</strong> Recoverable within 30 days.</li></ul><h2 id="uc-26-—-leave-workspace" tabindex="-1">UC-26 — Leave Workspace <a class="header-anchor" href="#uc-26-—-leave-workspace" aria-label="Permalink to &quot;UC-26 — Leave Workspace&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MEMBER</li><li><strong>Description:</strong> A member leaves a specific Workspace while remaining part of the Agency.</li><li><strong>Precondition:</strong> User is a member of the target Workspace.</li><li><strong>Main Flow:</strong><ol><li>MEMBER selects Leave Workspace, confirms.</li><li>System removes the member&#39;s Workspace-level role; Agency membership unaffected.</li></ol></li></ul><h2 id="uc-27-—-save-workspace-template" tabindex="-1">UC-27 — Save Workspace Template <a class="header-anchor" href="#uc-27-—-save-workspace-template" aria-label="Permalink to &quot;UC-27 — Save Workspace Template&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER</li><li><strong>Description:</strong> Save the current Workspace configuration as a template for reuse.</li><li><strong>Precondition:</strong> OWNER of parent Agency.</li><li><strong>Main Flow:</strong><ol><li>OWNER selects Save as Template on an existing Workspace.</li><li>System stores a reusable Workspace Template (config snapshot).</li></ol></li><li><strong>Postcondition:</strong> Template available for future Workspace creation (see UC-22 alternate entry point).</li></ul><h2 id="uc-28-—-view-workspace-members" tabindex="-1">UC-28 — View Workspace Members <a class="header-anchor" href="#uc-28-—-view-workspace-members" aria-label="Permalink to &quot;UC-28 — View Workspace Members&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER (any MEMBER can view per FR 3.4.18)</li><li><strong>Description:</strong> View the list of members belonging to a Workspace.</li><li><strong>Precondition:</strong> User is a member of the Workspace, or OWNER of parent Agency.</li><li><strong>Main Flow:</strong><ol><li>User opens Workspace Members screen.</li><li>System lists members with their Workspace-level role (MANAGER/MEMBER/CLIENT).</li></ol></li></ul><h2 id="uc-29-—-add-workspace-member" tabindex="-1">UC-29 — Add Workspace Member <a class="header-anchor" href="#uc-29-—-add-workspace-member" aria-label="Permalink to &quot;UC-29 — Add Workspace Member&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER</li><li><strong>Description:</strong> Add an Agency member into a Workspace with an assigned role.</li><li><strong>Precondition:</strong> Target user is already an Agency Member.</li><li><strong>Main Flow:</strong><ol><li>MANAGER selects an existing Agency Member, assigns a Workspace role.</li><li>System creates the Workspace membership with that role.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Target user is not yet an Agency Member → blocked; must be invited to Agency first (UC-18).</li></ul></li></ul><h2 id="uc-30-—-update-workspace-member-role" tabindex="-1">UC-30 — Update Workspace Member Role <a class="header-anchor" href="#uc-30-—-update-workspace-member-role" aria-label="Permalink to &quot;UC-30 — Update Workspace Member Role&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER</li><li><strong>Description:</strong> Update the role of an existing Workspace member.</li><li><strong>Precondition:</strong> Target is an existing Workspace member.</li><li><strong>Main Flow:</strong><ol><li>MANAGER selects member, changes assigned role.</li><li>System updates the Workspace-level role (role change applies only to this Workspace).</li></ol></li></ul><h2 id="uc-31-—-remove-workspace-member" tabindex="-1">UC-31 — Remove Workspace Member <a class="header-anchor" href="#uc-31-—-remove-workspace-member" aria-label="Permalink to &quot;UC-31 — Remove Workspace Member&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER</li><li><strong>Description:</strong> Remove a member from the Workspace.</li><li><strong>Precondition:</strong> Target is an existing Workspace member.</li><li><strong>Main Flow:</strong><ol><li>MANAGER selects member, confirms removal.</li><li>System removes Workspace-level membership only (Agency membership unaffected).</li></ol></li></ul>',43)])])}const h=t(a,[["render",s]]);export{m as __pageData,h as default};
